      if (message.type === "hd_status") return { ok: true, ready: true, loading: false, dictionaryCount: 2 };
      if (message.type === "hd_custom_read") return { ok: true, document: { schemaVersion: 1, revision: 0,
        semanticRevision: "a".repeat(64), text: "" } };
